        _key_candidates = ['PY_BANK_CUSTOMER_KEY', 'PY_KAFKA_KEY', 'customerKey', 'customer_key', 'partitionKey', 'partition_key', 'key', 'KEY', '_key', 'C_CUSTOMER_ID', 'CUSTOMER_ID', 'c_customer_id', 'T_TENANT_CODE', 'tenant_id', 'TENANT_ID', 'id', 'ID', 'Id']
        _target_key_setting = "key"
